+export const SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
+export type Size = (typeof SIZES)[number];
+export const MAX_SEED = 2147483646;
+export type Board = Readonly<{ code: string; size: Size; seed: number }>;
+
+export function isSize(value: unknown): value is Size {
+  return SIZES.some(size => size === value);
+}
+
+export function parseBoardCode(value: unknown): Board | null {
+  if (typeof value !== 'string' || !/^np1-(4|6|8|10|12|14|16)-[1-9][0-9]*$/.test(value)) return null;
+  const parts = value.split('-');
+  const size = Number(parts[1]);
+  const seed = Number(parts[2]);
+  if (!isSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
+  return Object.freeze({ code: value, size, seed });
+}
+
+export function generateDeck(board: Board): readonly number[] {
+  let state = board.seed;
+  function draw(bound: number): number {
+    const limit = Math.floor(MAX_SEED / bound) * bound;
+    do { state = (state * 16807) % 2147483647; } while (state - 1 >= limit);
+    return (state - 1) % bound;
+  }
+  const deck = Array.from({ length: board.size ** 2 }, (_, i) => Math.floor(i / 2));
+  for (let i = deck.length - 1; i > 0; i--) {
+    const j = draw(i + 1);
+    const first = deck[i];
+    const second = deck[j];
+    if (first !== undefined && second !== undefined) { deck[i] = second; deck[j] = first; }
+  }
+  return Object.freeze(deck);
+}
