+export function createGame(boardCode: string): GameState | null {
+  const board = parseBoardCode(boardCode);
+  if (!board) return null;
+  return { board, deck: generateDeck(board), matched: [], selection: { kind: 'closed' },
+    moves: 0, elapsedMs: 0, started: false };
+}
+
+export function isWon(state: GameState): boolean { return state.matched.length === state.deck.length; }
+export function pairCount(state: GameState): number { return state.matched.length / 2; }
