import { createGame } from './state.ts';
import type { GameState } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import { integer, objectWithKeys, parseJSON } from './validation.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_BYTES = 1048576;
export const MAX_ACTIONS = 10000;

export function replayGame(text: string): GameState | null {
  const value = parseJSON(text, REPLAY_BYTES);
  if (!objectWithKeys(value, ['version', 'boardCode', 'actions', 'endMs']) || value.version !== REPLAY_VERSION
    || typeof value.boardCode !== 'string' || !integer(value.endMs) || !Array.isArray(value.actions)
    || value.actions.length > MAX_ACTIONS) return null;
  let state = createGame(value.boardCode);
  if (!state) return null;
  let atMs = 0;
  for (const action of value.actions) {
    if (!objectWithKeys(action, ['atMs', 'index']) || !integer(action.atMs) || action.atMs < atMs
      || !integer(action.index, state.deck.length - 1)) return null;
    state = activateCard(advanceGame(state, action.atMs - atMs), action.index);
    atMs = action.atMs;
  }
  if (value.endMs < atMs) return null;
  return advanceGame(state, value.endMs - atMs);
}

/work/src/game/boardCode.ts.content:
export const SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type Size = (typeof SIZES)[number];
export const MAX_SEED = 2147483646;
export type Board = Readonly<{ code: string; size: Size; seed: number }>;

export function isSize(value: unknown): value is Size {
  return SIZES.some(size => size === value);
}

export function parseBoardCode(value: unknown): Board | null {
  if (typeof value !== 'string' || !/^np1-(4|6|8|10|12|14|16)-[1-9][0-9]*$/.test(value)) return null;
  const parts = value.split('-');
  const size = Number(parts[1]);
  const seed = Number(parts[2]);
  if (!isSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code: value, size, seed });
}

export function generateDeck(board: Board): readonly number[] {
  let state = board.seed;
  function draw(bound: number): number {
    const limit = Math.floor(MAX_SEED / bound) * bound;
    do { state = (state * 16807) % 2147483647; } while (state - 1 >= limit);
    return (state - 1) % bound;
  }
  const deck = Array.from({ length: board.size ** 2 }, (_, i) => Math.floor(i / 2));
  for (let i = deck.length - 1; i > 0; i--) {
    const j = draw(i + 1);
    const first = deck[i];
    const second = deck[j];
    if (first !== undefined && second !== undefined) { deck[i] = second; deck[j] = first; }
  }
  return Object.freeze(deck);
}

/work/src/game/state.ts.content:
import { generateDeck, parseBoardCode } from './boardCode.ts';
import type { Board } from './boardCode.ts';

export const SELECTION = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | Readonly<{ kind: typeof SELECTION.closed }>
  | Readonly<{ kind: typeof SELECTION.one; index: number }>
  | Readonly<{ kind: typeof SELECTION.mismatch; first: number; second: number; remainingMs: number }>;

export type GameState = Readonly<{
  board: Board;
  deck: readonly number[];
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return { board, deck: generateDeck(board), matched: [], selection: { kind: 'closed' },
    moves: 0, elapsedMs: 0, started: false };
}

export function isWon(state: GameState): boolean { return state.matched.length === state.deck.length; }
export function pairCount(state: GameState): number { return state.matched.length / 2; }

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case 'closed': return false;
    case 'one': return state.selection.index === index;
    case 'mismatch': return state.selection.first === index || state.selection.second === index;
  }
}

