import { createGame, isWon } from './state.ts';
import type { GameState, Selection } from './state.ts';
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_MS } from './transitions.ts';
import { integer, objectWithKeys, parseJSON } from './validation.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTES = 65536;
const FIELDS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === 'mismatch'
    ? { ...state.selection, remainingMs: Math.max(1, Math.floor(state.selection.remainingMs)) } : state.selection;
  return JSON.stringify({ version: SNAPSHOT_VERSION, boardCode: state.board.code,
    matched: state.matched, selection, moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs), started: state.started }, null, 2);
}

function parseSelection(value: unknown, eligible: (index: unknown) => index is number): Selection | null {
  if (objectWithKeys(value, ['kind']) && value.kind === 'closed') return { kind: 'closed' };
  if (objectWithKeys(value, ['kind', 'index']) && value.kind === 'one' && eligible(value.index)) {
    return { kind: 'one', index: value.index };
  }
  if (objectWithKeys(value, ['kind', 'first', 'second', 'remainingMs']) && value.kind === 'mismatch'
    && eligible(value.first) && eligible(value.second) && value.first !== value.second
    && integer(value.remainingMs, MISMATCH_MS) && value.remainingMs > 0) {
    return { kind: 'mismatch', first: value.first, second: value.second, remainingMs: value.remainingMs };
  }
  return null;
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseJSON(text, SNAPSHOT_BYTES);
  if (!objectWithKeys(value, FIELDS) || value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string') return null;
  const initial = createGame(value.boardCode);
  if (!initial || !Array.isArray(value.matched)) return null;
  const matched: number[] = [];
  for (const index of value.matched) {
    if (!integer(index, initial.deck.length - 1) || matched.includes(index)) return null;
    matched.push(index);
  }
  const faces = new Map<number, number>();
  for (const index of matched) {
    const face = initial.deck[index];
    if (face === undefined) return null;
    faces.set(face, (faces.get(face) ?? 0) + 1);
  }
  if ([...faces.values()].some(count => count !== 2)) return null;
  const eligible = (index: unknown): index is number => integer(index, initial.deck.length - 1) && !matched.includes(index);
  const selection = parseSelection(value.selection, eligible);
  if (!selection || (selection.kind === 'mismatch' && initial.deck[selection.first] === initial.deck[selection.second])) return null;
  if (!integer(value.moves, MAX_MOVES) || !integer(value.elapsedMs, MAX_ELAPSED_MS) || typeof value.started !== 'boolean') return null;
  const minimumMoves = matched.length / 2 + (selection.kind === 'mismatch' ? 1 : 0);
  if (value.moves < minimumMoves) return null;
  if (!value.started && (value.moves !== 0 || value.elapsedMs !== 0 || matched.length !== 0 || selection.kind !== 'closed')) return null;
  if (value.started && value.moves === 0 && selection.kind !== 'one') return null;
  const state = { ...initial, matched, selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started };
  if (isWon(state) && selection.kind !== 'closed') return null;
  return state;
}

