import { forwardRef, useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent } from 'react';
import type { GameState } from '../state.ts';
import { isRevealed } from '../state.ts';
import { Card } from './Card.tsx';
import './Board.css';

export type BoardHandle = { focusRemembered: () => void };
export type BoardProps = { game: GameState; paused: boolean; onActivate: (index: number) => void };

export const Board = forwardRef<BoardHandle, BoardProps>(function Board({ game, paused, onActivate }, ref) {
  const [tabStop, setTabStop] = useState(0);
  const buttons = useRef(new Map<number, HTMLButtonElement>());
  useImperativeHandle(ref, () => ({ focusRemembered: () => buttons.current.get(tabStop)?.focus() }), [tabStop]);
  function navigate(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const size = game.board.size;
    let destination = index;
    switch (event.key) {
      case 'ArrowLeft': if (index % size > 0) destination--; break;
      case 'ArrowRight': if (index % size < size - 1) destination++; break;
      case 'ArrowUp': if (index >= size) destination -= size; break;
      case 'ArrowDown': if (index < size * (size - 1)) destination += size; break;
      default: return;
    }
    event.preventDefault();
    buttons.current.get(destination)?.focus();
  }
  const style: CSSProperties & { '--columns': number } = { '--columns': game.board.size };
  return <div className="board-scroll" role="group" aria-label={`${game.board.size} by ${game.board.size} memory board`}>
    <div className="board-grid" style={style}>
      {game.deck.map((face, index) => <Card key={index} index={index} size={game.board.size}
        face={isRevealed(game, index) ? face : undefined} matched={game.matched.includes(index)}
        blocked={paused || game.selection.kind === 'mismatch'} tabIndex={tabStop === index ? 0 : -1}
        buttonRef={element => { if (element) buttons.current.set(index, element); else buttons.current.delete(index); }}
        onActivate={onActivate} onKeyDown={event => navigate(event, index)}
        onFocus={() => {
          setTabStop(index);
          buttons.current.get(index)?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        }} />)}
    </div>
  </div>;
});

