import { isSize, SIZES } from '../boardCode.ts';
import type { Size } from '../boardCode.ts';
import { MAX_MOVES } from '../transitions.ts';
import { integer } from '../validation.ts';

const KEY = 'neon-pairs.preferences.v1';
export type Preferences = { size: Size; best: Partial<Record<Size, number>> };

export function readPreferences(): Preferences {
  const preferences: Preferences = { size: 4, best: {} };
  try {
    const text = localStorage.getItem(KEY);
    const value: unknown = text ? JSON.parse(text) : null;
    if (typeof value !== 'object' || value === null) return preferences;
    if ('size' in value && isSize(value.size)) preferences.size = value.size;
    if ('best' in value && typeof value.best === 'object' && value.best !== null) {
      for (const size of SIZES) {
        const score: unknown = Reflect.get(value.best, String(size));
        if (integer(score, MAX_MOVES)) preferences.best[size] = score;
      }
    }
  } catch { /* Storage is optional; the in-memory session still works. */ }
  return preferences;
}

export function writePreferences(preferences: Preferences): void {
  try { localStorage.setItem(KEY, JSON.stringify(preferences)); } catch { /* Keep playing in memory. */ }
}

