import { MAX_SEED } from '../boardCode.ts';
import type { Size } from '../boardCode.ts';

export function freshCode(size: Size, previousSeed?: number): string {
  const values = new Uint32Array(1);
  crypto.getRandomValues(values);
  let seed = ((values[0] ?? 0) % MAX_SEED) + 1;
  if (seed === previousSeed) seed = seed === MAX_SEED ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}

