import { useEffect, useRef, useState } from 'react';
import type { Size } from '../boardCode.ts';
import { createGame, isWon, pairCount } from '../state.ts';
import type { GameState } from '../state.ts';
import { activateCard, advanceGame } from '../transitions.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { formatTime } from '../time.ts';
import { freshCode } from './seed.ts';
import { readPreferences, writePreferences } from './storage.ts';
import type { Preferences } from './storage.ts';

type View = {
  game: GameState; paused: boolean; epoch: number; celebrate: boolean;
  announcement: { id: number; text: string };
};

function initialView(preferences: Preferences): View {
  const game = createGame(freshCode(preferences.size));
  if (!game) throw new Error('Cannot create a supported board.');
  return { game, paused: false, epoch: 0, celebrate: false, announcement: { id: 0, text: '' } };
}

export function useGameSession() {
  const [preferences, setPreferences] = useState(readPreferences);
  const preferencesRef = useRef(preferences);
  const [view, setView] = useState(() => initialView(preferences));
  const current = useRef(view);
  const stamp = useRef(Math.floor(performance.now()));
  const shown = useRef(document.visibilityState !== 'hidden');

  function commit(next: View) { current.current = next; setView(next); }
  function save(next: Preferences) {
    preferencesRef.current = next; setPreferences(next); writePreferences(next);
  }
  function sync() {
    const now = Math.floor(performance.now());
    const before = current.current;
    if (shown.current && !before.paused) {
      const game = advanceGame(before.game, Math.max(0, now - stamp.current));
      if (game !== before.game) commit({ ...before, game });
    }
    stamp.current = now;
    return current.current;
  }
  function announce(text: string) {
    const before = current.current;
    commit({ ...before, announcement: { id: before.announcement.id + 1, text } });
  }

  useEffect(() => {
    let alive = true;
    const epoch = current.current.epoch;
    const tick = () => { if (alive && current.current.epoch === epoch) sync(); };
    const timer = window.setInterval(tick, 32);
    function visibility() {
      if (!alive || current.current.epoch !== epoch) return;
      sync();
      shown.current = document.visibilityState !== 'hidden';
    }
    document.addEventListener('visibilitychange', visibility);
    return () => { alive = false; clearInterval(timer); document.removeEventListener('visibilitychange', visibility); };
  }, [view.epoch]);

  function replace(game: GameState, paused: boolean, message = '') {
    const before = current.current;
    stamp.current = Math.floor(performance.now());
    shown.current = document.visibilityState !== 'hidden';
    commit({ game, paused, celebrate: false, epoch: before.epoch + 1,
      announcement: { id: before.announcement.id + 1, text: message } });
    save({ ...preferencesRef.current, size: game.board.size });
  }
  function start(size = current.current.game.board.size, restart = false) {
    const previous = current.current.game;
    const code = restart ? previous.board.code : freshCode(size, previous.board.seed);
    const game = createGame(code);
    if (game) replace(game, false);
  }
  function activate(index: number) {
    const before = sync();
    if (before.paused) return;
    const game = activateCard(before.game, index);
    if (game === before.game) return;
    let text = before.announcement.text;
    let id = before.announcement.id;
    const won = isWon(game);
    if (before.game.selection.kind === 'one') {
      id++;
      const pairs = pairCount(game);
      text = game.selection.kind === 'mismatch' ? 'No match. Cards close after a short pause.'
        : won ? `Pair found. All pairs found in ${game.moves} moves and ${formatTime(game.elapsedMs)}.`
        : `Pair found. ${pairs} ${pairs === 1 ? 'pair' : 'pairs'} matched.`;
    }
    commit({ ...before, game, celebrate: won, announcement: { id, text } });
    if (won) {
      const saved = preferencesRef.current;
      const best = saved.best[game.board.size];
      if (best === undefined || game.moves < best) save({ ...saved, best: { ...saved.best, [game.board.size]: game.moves } });
    }
  }
  function loadBoard(text: string): boolean {
    const game = createGame(text.trim());
    if (!game) { announce('Invalid board code.'); return false; }
    replace(game, false);
    return true;
  }
  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) { announce('Invalid snapshot.'); return false; }
    const won = isWon(game);
    replace(game, !won, won ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
    return true;
  }
  function resume() {
    stamp.current = Math.floor(performance.now());
    commit({ ...current.current, paused: false });
  }
  return { ...view, best: preferences.best[view.game.board.size], activate, start, loadBoard, loadSnapshot,
    resume, exportSnapshot: () => encodeSnapshot(sync().game) };
}

