import { useRef } from 'react';
import { Board } from './board/Board.tsx';
import type { BoardHandle } from './board/Board.tsx';
import { DealControls } from './controls/DealControls.tsx';
import { ReproductionControls } from './controls/ReproductionControls.tsx';
import { useGameSession } from './session/useGameSession.ts';
import { Status } from './Status.tsx';
import './Game.css';

export function Game() {
  const session = useGameSession();
  const board = useRef<BoardHandle>(null);
  return <main>
    <header className="masthead">
      <div className="brand"><span className="brand-mark" aria-hidden="true">◇</span><h1>Neon Pairs<span className="brand-dot">.</span></h1></div>
      <span className="edition">A GAME OF MEMORY</span>
    </header>
    <div className="game-layout">
      <aside className="introduction">
        <span className="eyebrow"><span aria-hidden="true">✦</span> A LITTLE FOCUS. A LITTLE MEMORY.</span>
        <h2>Find your<br /><span>other half.</span></h2>
        <p>Turn over two cards. Remember what you see. Find every pair in as few moves as you can.</p>
        <div className="how-to"><span className="instruction-number">01</span><p>Reveal. Remember. Repeat.</p></div>
        <div className="how-to"><span className="instruction-number">02</span><p>Same shape, same marker.<br />You’ve found a pair.</p></div>
        <p className="quiet-note"><span aria-hidden="true">◌</span> No rush. Just you and your memory.</p>
      </aside>
      <section className="play-area" aria-label="Neon Pairs game">
        <DealControls size={session.game.board.size} onStart={session.start} />
        <Status game={session.game} best={session.best} celebrate={session.celebrate} />
        {session.paused && <div className="pause-banner"><p>Snapshot paused. Ready when you are.</p>
          <button type="button" className="primary-button" onClick={() => {
            board.current?.focusRemembered(); session.resume();
          }}>Resume</button></div>}
        <Board key={session.epoch} ref={board} game={session.game} paused={session.paused} onActivate={session.activate} />
        <p className="board-help">Click or tap to reveal <span aria-hidden="true">·</span> Arrow keys to explore <span aria-hidden="true">·</span> Enter or Space to flip</p>
        <ReproductionControls key={session.epoch} code={session.game.board.code}
          onLoadBoard={session.loadBoard} onLoadSnapshot={session.loadSnapshot} onExport={session.exportSnapshot} />
      </section>
    </div>
    <footer><span>Made for a moment of clarity.</span><span>PLAY. AT YOUR OWN PACE.</span></footer>
    <div className="sr-only" aria-live="polite" aria-atomic="true"><span key={session.announcement.id}>{session.announcement.text}</span></div>
  </main>;
}

