.game-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.65fr); gap: 32px; padding: 32px 0; }
.introduction { padding: 24px 0; }
.eyebrow { display: flex; align-items: center; gap: 8px; font-size: 12px; letter-spacing: 1px; }
.eyebrow > span { color: var(--cyan); font-size: 20px; }
.introduction h2 { font-size: clamp(32px, 4vw, 48px); line-height: 1.15; letter-spacing: -1.5px;
  font-weight: 500; margin: 24px 0; }
.introduction h2 > span { color: var(--cyan); }
.introduction > p { max-width: 320px; color: var(--secondary); }
.how-to { display: flex; align-items: baseline; gap: 12px; margin-top: 24px; font-size: 14px; }
.instruction-number { color: var(--cyan); font-size: 12px; font-variant-numeric: tabular-nums; }
.introduction .quiet-note { margin-top: 32px; font-size: 14px; }
.quiet-note span { color: var(--cyan); margin-right: 8px; }
.play-area { min-width: 0; }
.play-area .deal-controls { margin-bottom: 24px; }
.board-help { color: var(--secondary); text-align: center; font-size: 14px; margin-top: 12px; }
.board-help span { margin: 0 4px; }
.help { font-size: 14px; color: var(--secondary); }
.pause-banner { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap;
  gap: 12px; margin-bottom: 12px; font-size: 14px; color: var(--secondary); }
footer { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 24px 0;
  border-top: 1px solid var(--border); color: var(--secondary); font-size: 14px; }
footer span:last-child { font-size: 12px; letter-spacing: 1px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 760px) {
  .game-layout { grid-template-columns: minmax(0, 1fr); gap: 24px; padding: 24px 0; }
  .introduction { padding: 0; }
  .introduction h2 { font-size: 32px; margin: 12px 0; }
  .introduction h2 br { display: none; }
  .introduction h2 > span::before { content: ' '; }
  .introduction > p { max-width: none; font-size: 14px; }
  .how-to, .quiet-note, .edition { display: none; }
  .masthead { padding: 8px 0 16px; }
  .eyebrow { font-size: 12px; }
}

