import { useState } from 'react';
import './ReproductionControls.css';

export type ReproductionControlsProps = {
  code: string; onLoadBoard: (text: string) => boolean;
  onLoadSnapshot: (text: string) => boolean; onExport: () => string;
};

export function ReproductionControls({ code, onLoadBoard, onLoadSnapshot, onExport }: ReproductionControlsProps) {
  const [boardDraft, setBoardDraft] = useState(code);
  const [snapshotDraft, setSnapshotDraft] = useState('');
  const [boardStatus, setBoardStatus] = useState('');
  const [snapshotStatus, setSnapshotStatus] = useState('');
  return <details className="reproduction">
    <summary>Reproduce a game</summary>
    <div className="reproduction-content">
      <p className="help">Repeat a deal with its board code, or save your place with a snapshot.</p>
      <div className="board-code-controls">
        <label htmlFor="board-code">Board code</label>
        <div className="code-row">
          <input id="board-code" type="text" maxLength={32} autoCapitalize="off" spellCheck={false}
            value={boardDraft} onChange={event => setBoardDraft(event.target.value)} aria-describedby="board-status" />
          <button type="button" onClick={() => setBoardStatus(onLoadBoard(boardDraft) ? '' : 'Invalid board code.')}>Load board</button>
        </div>
        <p id="board-status" className="load-status">{boardStatus}</p>
      </div>
      <label htmlFor="snapshot-json">Snapshot JSON</label>
      <textarea id="snapshot-json" maxLength={65536} rows={5} spellCheck={false}
        value={snapshotDraft} onChange={event => setSnapshotDraft(event.target.value)} aria-describedby="snapshot-status" />
      <div className="snapshot-actions">
        <button type="button" onClick={() => { setSnapshotDraft(onExport()); setSnapshotStatus(''); }}>Export snapshot</button>
        <button type="button" onClick={() => {
          const valid = onLoadSnapshot(snapshotDraft);
          if (!valid) { setSnapshotStatus('Invalid snapshot.'); return; }
          const parsed: unknown = JSON.parse(snapshotDraft);
          const completed = typeof parsed === 'object' && parsed !== null && 'matched' in parsed && Array.isArray(parsed.matched)
            && 'boardCode' in parsed && typeof parsed.boardCode === 'string'
            && parsed.matched.length === Number(parsed.boardCode.split('-')[1]) ** 2;
          setSnapshotStatus(completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
        }}>Load snapshot</button>
      </div>
      <p id="snapshot-status" className="load-status">{snapshotStatus}</p>
    </div>
  </details>;
}

