+import { activateCard, advanceGame, MAX_ELAPSED_MS, MAX_MOVES } from './transitions.ts';
+import { formatTime } from './time.ts';
+
+function initial(): GameState {
+  const game = createGame('np1-4-1');
+  if (!game) throw new Error('Invalid fixture');
+  return game;
+}
+
+describe('turns and active time', () => {
+  it('starts only on a valid reveal and ignores repeated and matched cards', () => {
+    const hidden = initial();
+    expect(advanceGame(hidden, 9000)).toBe(hidden);
+    expect(activateCard(hidden, -1)).toBe(hidden);
+    const one = activateCard(hidden, 0);
+    expect(one.started).toBe(true);
+    expect(one.moves).toBe(0);
+    expect(activateCard(one, 0)).toBe(one);
+    const matched = activateCard(one, 11);
+    expect(matched.moves).toBe(1);
+    expect(pairCount(matched)).toBe(1);
+    expect(activateCard(matched, 0)).toBe(matched);
+    expect(hidden.selection.kind).toBe('closed');
+    expect(hidden.matched).toEqual([]);
+  });
