import { describe, expect, it } from 'vitest';
import { createGame } from './state.ts';
import { activateCard, advanceGame } from './transitions.ts';
import { decodeSnapshot, encodeSnapshot } from './snapshot.ts';

const base = { version: 1, boardCode: 'np1-4-1', matched: [0, 11],
  selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 }, moves: 2, elapsedMs: 1500, started: true };

describe('strict version 1 snapshots', () => {
  it('accepts the documented progress and round trips all selection states', () => {
    expect(decodeSnapshot(JSON.stringify(base))?.selection).toEqual(base.selection);
    const initial = createGame('np1-4-1');
    if (!initial) throw new Error('Invalid fixture');
    const one = activateCard(initial, 0);
    const miss = advanceGame(activateCard(one, 1), 123);
    const match = activateCard(one, 11);
    for (const state of [initial, one, miss, match]) expect(decodeSnapshot(encodeSnapshot(state))).toEqual(state);
  });
  const invalid: Record<string, unknown>[] = [
    { surprise: 1 }, { version: 2 }, { boardCode: ' np1-4-1' }, { matched: [0] }, { matched: [0, 1] },
    { matched: [0, 11, 0, 11] }, { matched: [-1, 16] }, { moves: 1 }, { moves: 1000000 }, { moves: 1.1 },
    { moves: '2' }, { elapsedMs: 360000000 }, { elapsedMs: -1 }, { started: 1 }, { started: false },
    { selection: { kind: 'closed', extra: 1 } }, { selection: { kind: 'one', index: 0 } },
    { selection: { kind: 'one', index: 16 } }, { selection: { kind: 'one', index: 1, extra: 1 } },
    { selection: { kind: 'mismatch', first: 1, second: 9, remainingMs: 800 } },
    { selection: { kind: 'mismatch', first: 1, second: 1, remainingMs: 800 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 0 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 801 } },
    { selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 1.5 } },
  ];
  it.each(invalid)('rejects inconsistent progress %j', change => {
    expect(decodeSnapshot(JSON.stringify({ ...base, ...change }))).toBeNull();
  });
  it('validates started and completed states without reconstructing a history', () => {
    const fresh = { ...base, matched: [], selection: { kind: 'closed' }, moves: 0, elapsedMs: 0, started: false };
    expect(decodeSnapshot(JSON.stringify(fresh))).not.toBeNull();
    expect(decodeSnapshot(JSON.stringify({ ...fresh, started: true }))).toBeNull();
    expect(decodeSnapshot(JSON.stringify({ ...fresh, started: true, selection: { kind: 'one', index: 5 } }))).not.toBeNull();
    const done = { ...base, matched: Array.from({ length: 16 }, (_, i) => i), selection: { kind: 'closed' }, moves: 8 };
    expect(decodeSnapshot(JSON.stringify(done))).not.toBeNull();
    expect(decodeSnapshot(JSON.stringify({ ...done, moves: 7 }))).toBeNull();
    expect(decodeSnapshot(JSON.stringify({ ...base, moves: 999999, elapsedMs: 359999999 }))).not.toBeNull();
  });
  it('enforces UTF-8 byte size and malformed JSON rejection', () => {
    expect(decodeSnapshot('{')).toBeNull();
    expect(decodeSnapshot('null')).toBeNull();
    expect(decodeSnapshot('[]')).toBeNull();
    expect(decodeSnapshot(JSON.stringify(base) + ' '.repeat(65536))).toBeNull();
    expect(decodeSnapshot(JSON.stringify({ ...base, boardCode: 'é'.repeat(33000) }))).toBeNull();
  });
});

