import { describe, expect, it } from 'vitest';
import { createGame, isWon, pairCount } from './state.ts';
import type { GameState } from './state.ts';
import { activateCard, advanceGame, MAX_ELAPSED_MS, MAX_MOVES } from './transitions.ts';
import { formatTime } from './time.ts';

function initial(): GameState {
  const game = createGame('np1-4-1');
  if (!game) throw new Error('Invalid fixture');
  return game;
}

describe('turns and active time', () => {
  it('starts only on a valid reveal and ignores repeated and matched cards', () => {
    const hidden = initial();
    expect(advanceGame(hidden, 9000)).toBe(hidden);
    expect(activateCard(hidden, -1)).toBe(hidden);
    const one = activateCard(hidden, 0);
    expect(one.started).toBe(true);
    expect(one.moves).toBe(0);
    expect(activateCard(one, 0)).toBe(one);
    const matched = activateCard(one, 11);
    expect(matched.moves).toBe(1);
    expect(pairCount(matched)).toBe(1);
    expect(activateCard(matched, 0)).toBe(matched);
    expect(hidden.selection.kind).toBe('closed');
    expect(hidden.matched).toEqual([]);
  });
  it('blocks a mismatch for exactly 800 active milliseconds', () => {
    const miss = activateCard(activateCard(initial(), 0), 1);
    expect(miss.moves).toBe(1);
    expect(activateCard(miss, 2)).toBe(miss);
    const almost = advanceGame(miss, 799);
    expect(almost.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 1 });
    expect(advanceGame(almost, 1).selection).toEqual({ kind: 'closed' });
    expect(advanceGame(miss, 900).elapsedMs).toBe(900);
  });
  it('completes every pair and stops the clock', () => {
    let game = initial();
    for (let face = 0; face < 8; face++) {
      const first = game.deck.indexOf(face);
      const second = game.deck.lastIndexOf(face);
      game = activateCard(advanceGame(activateCard(game, first), 1000), second);
    }
    expect(isWon(game)).toBe(true);
    expect(game.moves).toBe(8);
    expect(game.elapsedMs).toBe(8000);
    expect(advanceGame(game, 10000)).toBe(game);
  });
  it('keeps play working at both caps', () => {
    let game = { ...activateCard(initial(), 0), moves: MAX_MOVES, elapsedMs: MAX_ELAPSED_MS - 1 };
    game = advanceGame(game, 9999);
    game = activateCard(game, 11);
    expect(game.moves).toBe(MAX_MOVES);
    expect(game.elapsedMs).toBe(MAX_ELAPSED_MS);
    expect(pairCount(game)).toBe(1);
    expect(formatTime(game.elapsedMs)).toBe('5999:59');
    expect(formatTime(3600000)).toBe('60:00');
  });
});

