import { describe, expect, it } from 'vitest';
import { replayGame } from './replay.ts';

const base = { version: 1, boardCode: 'np1-4-1', actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800 };

describe('version 1 replay', () => {
  it('reproduces the documented match', () => {
    const state = replayGame(JSON.stringify(base));
    expect(state?.matched).toEqual([0, 11]);
    expect(state?.moves).toBe(1);
    expect(state?.elapsedMs).toBe(800);
  });
  it('resolves the exact timeout before an equal-time action', () => {
    const state = replayGame(JSON.stringify({ ...base, actions: [
      { atMs: 0, index: 0 }, { atMs: 0, index: 1 }, { atMs: 799, index: 2 },
      { atMs: 800, index: 2 }, { atMs: 800, index: 6 },
    ] }));
    expect(state?.matched).toEqual([2, 6]);
    expect(state?.moves).toBe(2);
    expect(state?.selection).toEqual({ kind: 'closed' });
  });
  it('ignores pre-start time and caps huge safe logical timestamps', () => {
    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 500, index: 0 }], endMs: 1500 }))?.elapsedMs).toBe(1000);
    expect(replayGame(JSON.stringify({ ...base, endMs: Number.MAX_SAFE_INTEGER }))?.elapsedMs).toBe(359999999);
    expect(replayGame(JSON.stringify({ ...base, actions: [], endMs: Number.MAX_SAFE_INTEGER }))?.elapsedMs).toBe(0);
  });
  it.each([
    { extra: 1 }, { version: 2 }, { actions: [{ atMs: 0, index: 16 }] }, { actions: [{ atMs: -1, index: 0 }] },
    { actions: [{ atMs: 0, index: 0, extra: 1 }] }, { actions: [{ atMs: 1, index: 0 }, { atMs: 0, index: 1 }] },
    { endMs: -1 }, { endMs: 1.5 }, { endMs: Number.MAX_SAFE_INTEGER + 1 },
    { actions: [{ atMs: 801, index: 0 }] }, { actions: Array.from({ length: 10001 }, () => ({ atMs: 0, index: 0 })) },
  ])('rejects invalid replay %j', change => {
    expect(replayGame(JSON.stringify({ ...base, ...change }))).toBeNull();
  });
  it('enforces JSON and byte limits', () => {
    expect(replayGame('null')).toBeNull();
    expect(replayGame('{')).toBeNull();
    expect(replayGame(JSON.stringify(base) + ' '.repeat(1048576))).toBeNull();
  });
});

