import { describe, expect, it } from 'vitest';
import { generateDeck, parseBoardCode, SIZES } from './boardCode.ts';

describe('version 1 board codes', () => {
  it('matches independent literal vectors', () => {
    const four = parseBoardCode('np1-4-1');
    const six = parseBoardCode('np1-6-2147483646');
    if (!four || !six) throw new Error('Valid vector rejected');
    expect(generateDeck(four)).toEqual([6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3]);
    // Independently computed with Python integer arithmetic, not this implementation.
    expect(generateDeck(six)).toEqual([17, 2, 10, 5, 15, 4, 12, 10, 0, 17, 5, 15, 2, 6, 8, 7, 12, 1,
      0, 11, 16, 1, 16, 9, 3, 14, 13, 13, 4, 6, 7, 14, 8, 9, 3, 11]);
  });
  it.each(SIZES)('makes exactly two of each face on size %i', size => {
    const board = parseBoardCode(`np1-${size}-12345`);
    if (!board) throw new Error('Supported size rejected');
    const deck = generateDeck(board);
    expect(Object.isFrozen(board)).toBe(true);
    expect(Object.isFrozen(deck)).toBe(true);
    expect(deck).toHaveLength(size ** 2);
    for (let face = 0; face < size ** 2 / 2; face++) expect(deck.filter(value => value === face)).toHaveLength(2);
  });
  it.each(['np1-04-1', 'np1-4-01', 'np1-4-0', 'np1-4-2147483647', 'np1-5-1', 'np2-4-1',
    ' np1-4-1', 'np1-4-1\n', 'np1-4-1e2', 'np1-4-+1', 'np1-4-1.0', 'np1-4-١'])('rejects %s', text => {
    expect(parseBoardCode(text)).toBeNull();
  });
});

