import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { generateDeck, parseBoardCode } from '../src/game/boardCode.ts';

export async function openTools(page: Page) {
  const details = page.locator('details');
  if (!(await details.getAttribute('open') !== null)) await page.getByText('Reproduce a game', { exact: true }).click();
}

export async function loadBoard(page: Page, code = 'np1-4-1') {
  await openTools(page);
  await page.getByLabel('Board code', { exact: true }).fill(code);
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
}

export async function loadSnapshot(page: Page, value: unknown) {
  await openTools(page);
  await page.getByLabel('Snapshot JSON').fill(typeof value === 'string' ? value : JSON.stringify(value));
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
}

export function deckFor(code: string): readonly number[] {
  const board = parseBoardCode(code);
  if (!board) throw new Error('Invalid test board');
  return generateDeck(board);
}

export async function solve(page: Page, code = 'np1-4-1') {
  const deck = deckFor(code);
  const cards = page.locator('.card');
  for (let face = 0; face < deck.length / 2; face++) {
    await cards.nth(deck.indexOf(face)).click();
    await cards.nth(deck.lastIndexOf(face)).click();
  }
  await expect(page.getByRole('heading', { name: 'All pairs found.' })).toBeVisible();
}

export function snapshot(overrides: Record<string, unknown> = {}) {
  return { version: 1, boardCode: 'np1-4-1', matched: [0, 11],
    selection: { kind: 'mismatch', first: 1, second: 2, remainingMs: 300 },
    moves: 2, elapsedMs: 1500, started: true, ...overrides };
}

export async function expectStat(page: Page, label: string, value: string) {
  await expect(page.locator('.scoreboard p').filter({ hasText: `${label}:` })).toHaveText(`${label}: ${value}`);
}

