import { test, expect } from '@playwright/test';
import { expectStat, loadBoard, loadSnapshot, openTools, snapshot } from './helpers.ts';

test.beforeEach(async ({ page }) => { await page.goto('/'); });

test('strict board drafts, focus retention, errors and resets', async ({ page }) => {
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await openTools(page);
  await expect(page.getByLabel('Board code', { exact: true })).toHaveAttribute('maxlength', '32');
  await expect(page.getByLabel('Snapshot JSON')).toHaveAttribute('maxlength', '65536');
  await loadBoard(page, ' np1-6-1 ');
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-6-1');
  await expect(page.getByRole('button', { name: 'Load board', exact: true })).toBeFocused();
  await page.getByLabel('Board code', { exact: true }).fill('draft');
  await page.locator('.card').first().click();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('draft');
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(page.locator('#board-status')).toHaveText('Invalid board code.');
  await expect(page.locator('[aria-live]')).toHaveText('Invalid board code.');
  await expect(page.locator('.revealed')).toHaveCount(1);
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveValue('np1-6-1');
  await expect(page.locator('.card[tabindex="0"]')).toHaveAccessibleName('Row 1, column 1, closed');
});

test('snapshot export, paused import, Resume focus and remaining time', async ({ page }) => {
  await page.clock.install();
  await loadSnapshot(page, snapshot());
  await expect(page.getByRole('button', { name: 'Load snapshot', exact: true })).toBeFocused();
  await expect(page.locator('#snapshot-status')).toHaveText('Loaded snapshot. Select Resume to continue.');
  await page.clock.runFor(5000);
  await expectStat(page, 'Time', '0:01');
  const cards = page.locator('.card');
  await cards.nth(4).click();
  await page.keyboard.press('ArrowRight');
  await expect(cards.nth(5)).toBeFocused();
  await expectStat(page, 'Moves', '2');
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Export snapshot', exact: true })).toBeFocused();
  const exported: unknown = JSON.parse(await page.getByLabel('Snapshot JSON').inputValue());
  expect(exported).toEqual(snapshot());
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await expect(cards.nth(5)).toBeFocused();
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await page.clock.runFor(299);
  await expect(cards.nth(1)).toHaveAccessibleName(/revealed/);
  await page.clock.runFor(1);
  await expect(cards.nth(1)).toHaveAccessibleName(/closed/);
  await page.clock.runFor(700);
  await expectStat(page, 'Time', '0:02');
});

test('invalid snapshots keep drafts and game; completed imports are static and do not write best', async ({ page }) => {
  await loadBoard(page);
  await page.locator('.card').first().click();
  await loadSnapshot(page, '{broken');
  await expect(page.getByLabel('Snapshot JSON')).toHaveValue('{broken');
  await expect(page.locator('#snapshot-status')).toHaveText('Invalid snapshot.');
  await expect(page.locator('.revealed')).toHaveCount(1);
  const complete = snapshot({ matched: Array.from({ length: 16 }, (_, i) => i), selection: { kind: 'closed' }, moves: 8 });
  await loadSnapshot(page, complete);
  await expect(page.locator('#snapshot-status')).toHaveText('Loaded completed snapshot.');
  await expect(page.locator('.win-banner')).toBeVisible();
  await expect(page.locator('.win-banner')).not.toHaveClass(/celebrate/);
  await expectStat(page, 'Best', 'none');
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Load snapshot', exact: true })).toBeFocused();
});

