import { test, expect } from '@playwright/test';
import { SIZES } from '../src/game/boardCode.ts';
import { expectStat, loadBoard, solve } from './helpers.ts';

test.beforeEach(async ({ page }) => { await page.goto('/'); });

for (const size of SIZES) {
  test(`finish a ${size}x${size} board with complete pairs`, async ({ page }) => {
    test.setTimeout(90000);
    const code = `np1-${size}-1`;
    await loadBoard(page, code);
    await expect(page.getByLabel('Grid size')).toHaveValue(String(size));
    await expect(page.locator('.card')).toHaveCount(size ** 2);
    await solve(page, code);
    await expectStat(page, 'Moves', String(size ** 2 / 2));
    await expectStat(page, 'Pairs', `${size ** 2 / 2}/${size ** 2 / 2}`);
    await expectStat(page, 'Best', String(size ** 2 / 2));
    await expect(page.locator('[aria-live]')).toHaveText(new RegExp(`All pairs found in ${size ** 2 / 2} moves`));
  });
}

test('repeated activation, immediate matches, exact mismatch delay and stale timers', async ({ page }) => {
  await page.clock.install();
  await loadBoard(page);
  const cards = page.locator('.card');
  await cards.nth(0).click();
  await cards.nth(0).click();
  await expectStat(page, 'Moves', '0');
  await cards.nth(11).click();
  await expectStat(page, 'Pairs', '1/8');
  await cards.nth(1).click();
  await cards.nth(2).click();
  await expectStat(page, 'Moves', '2');
  await cards.nth(3).click();
  await expect(cards.nth(3)).toHaveAccessibleName('Row 1, column 4, closed');
  await page.clock.runFor(799);
  await expect(cards.nth(1)).toHaveAccessibleName(/revealed/);
  await page.clock.runFor(1);
  await expect(cards.nth(1)).toHaveAccessibleName(/closed/);
  await cards.nth(1).click();
  await cards.nth(2).click();
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expect(page.getByRole('button', { name: 'Restart', exact: true })).toBeFocused();
  await cards.nth(4).click();
  await page.clock.runFor(1000);
  await expect(cards.nth(4)).toHaveAccessibleName(/revealed/);
  await expectStat(page, 'Moves', '0');
  await expectStat(page, 'Pairs', '0/8');
  await cards.nth(1).click();
  await page.getByRole('button', { name: 'New Game', exact: true }).click();
  await expect(page.getByRole('button', { name: 'New Game', exact: true })).toBeFocused();
  await page.clock.runFor(1000);
  await expect(page.locator('.revealed')).toHaveCount(0);
  await expectStat(page, 'Time', '0:00');
});

test('hidden-page time pauses both the clock and the mismatch', async ({ page }) => {
  await page.clock.install();
  await loadBoard(page);
  const cards = page.locator('.card');
  await cards.nth(0).click();
  await cards.nth(1).click();
  await page.clock.runFor(500);
  // An adapter event with a hidden document: browser automation cannot background a headless tab reliably.
  await page.evaluate(() => {
    Object.defineProperty(document, 'visibilityState', { configurable: true, value: 'hidden' });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(5000);
  await expectStat(page, 'Time', '0:00');
  await expect(cards.nth(0)).toHaveAccessibleName(/revealed/);
  await page.evaluate(() => {
    Object.defineProperty(document, 'visibilityState', { configurable: true, value: 'visible' });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(299);
  await expect(cards.nth(0)).toHaveAccessibleName(/revealed/);
  await page.clock.runFor(1);
  await expect(cards.nth(0)).toHaveAccessibleName(/closed/);
  await page.clock.runFor(1200);
  await expectStat(page, 'Time', '0:02');
});

test('pointer cancellation, hover and context menu leave cards closed; taps activate', async ({ page, browser }) => {
  const card = page.locator('.card').first();
  await card.hover();
  await card.click({ button: 'right' });
  await card.dispatchEvent('pointercancel');
  await expect(card).toHaveAccessibleName(/closed/);
  await expectStat(page, 'Moves', '0');
  const touch = await browser.newContext({ hasTouch: true, viewport: { width: 360, height: 800 } });
  const touchPage = await touch.newPage();
  await touchPage.goto('/');
  await touchPage.locator('.card').first().tap();
  await expect(touchPage.locator('.card').first()).toHaveAccessibleName(/revealed/);
  await touch.close();
});

