import { test, expect } from '@playwright/test';
import { expectStat, loadBoard, loadSnapshot, snapshot, solve } from './helpers.ts';

test('best scores survive reload, improve, and keep equal/worse results', async ({ page }) => {
  await page.goto('/');
  await page.evaluate(() => localStorage.setItem('unrelated', 'keep me'));
  // Finish unfinished imports with different move counts through normal play.
  for (const [priorMoves, expected] of [[19, '20'], [19, '20'], [29, '20'], [9, '10']]) {
    if (typeof priorMoves !== 'number' || typeof expected !== 'string') throw new Error('Invalid fixture');
    await loadSnapshot(page, snapshot({ matched: Array.from({ length: 16 }, (_, i) => i).filter(i => i !== 0 && i !== 11),
      selection: { kind: 'closed' }, moves: priorMoves }));
    await page.getByRole('button', { name: 'Resume', exact: true }).click();
    await page.locator('.card').nth(0).click();
    await page.locator('.card').nth(11).click();
    await expectStat(page, 'Best', expected);
    await page.reload();
    await expectStat(page, 'Best', expected);
    await expectStat(page, 'Moves', '0');
  }
  await loadBoard(page, 'np1-6-1');
  await expectStat(page, 'Best', 'none');
  await page.reload();
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await loadBoard(page);
  await expectStat(page, 'Best', '10');
  expect(await page.evaluate(() => localStorage.getItem('unrelated'))).toBe('keep me');
});

test('saved preferences are validated, failed loads keep size, and storage failure leaves play working', async ({ page }) => {
  await page.addInitScript(() => {
    localStorage.setItem('neon-pairs.preferences.v1', JSON.stringify({ size: 6, best: { 6: 999999, 4: 1000000 } }));
  });
  await page.goto('/');
  await expect(page.getByLabel('Grid size')).toHaveValue('6');
  await expectStat(page, 'Best', '999999');
  await loadBoard(page, 'np1-4-0');
  await loadSnapshot(page, '{}');
  const stored: unknown = await page.evaluate(() => JSON.parse(localStorage.getItem('neon-pairs.preferences.v1') ?? 'null'));
  expect(stored).toMatchObject({ size: 6 });
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', { get() { throw new Error('Unavailable'); } });
  });
  await page.reload();
  await loadBoard(page);
  await solve(page);
  await expectStat(page, 'Best', '8');
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expectStat(page, 'Best', '8');
});

test('caps still allow an imported unfinished game to complete', async ({ page }) => {
  await page.goto('/');
  await loadSnapshot(page, snapshot({ matched: Array.from({ length: 16 }, (_, i) => i).filter(i => i !== 0 && i !== 11),
    selection: { kind: 'closed' }, moves: 999999, elapsedMs: 359999999 }));
  await expectStat(page, 'Time', '5999:59');
  await page.getByRole('button', { name: 'Resume', exact: true }).click();
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(11).click();
  await expect(page.locator('.win-banner')).toContainText('999999 moves');
  await expectStat(page, 'Best', '999999');
});

