import { mkdirSync, writeFileSync } from 'node:fs';
import { test, expect } from '@playwright/test';
import { deckFor, expectStat, loadBoard } from './helpers.ts';

test('complete keyboard journey with accessibility-tree evidence', async ({ page, browser }) => {
  await page.goto('/');
  expect(await page.evaluate(() => document.activeElement === document.body)).toBe(true);
  await loadBoard(page);
  const cards = page.locator('.card');
  const closedTree = await page.locator('main').ariaSnapshot();
  expect(closedTree).toContain('Row 1, column 1, closed');
  expect(closedTree).not.toContain('cyan');
  await expect(cards.first().locator('.face-art')).toHaveCount(0);
  const hiddenMarkup = await cards.first().evaluate(element => element.outerHTML);
  expect(hiddenMarkup).not.toMatch(/data-face|face-id|circle|solid|outline|cyan/);
  await page.getByRole('button', { name: 'New Game', exact: true }).focus();
  await page.keyboard.press('Tab');
  await expect(page.getByRole('button', { name: 'Restart', exact: true })).toBeFocused();
  await page.keyboard.press('Tab');
  await expect(cards.first()).toBeFocused();
  await page.keyboard.press('ArrowLeft');
  await page.keyboard.press('ArrowUp');
  await expect(cards.first()).toBeFocused();
  await page.keyboard.press('Shift+ArrowRight');
  await page.keyboard.press('Home');
  await expect(cards.first()).toBeFocused();
  await page.keyboard.press('ArrowRight');
  await page.keyboard.press('Tab');
  await expect(page.getByText('Reproduce a game', { exact: true })).toBeFocused();
  await page.keyboard.press('Shift+Tab');
  await expect(cards.nth(1)).toBeFocused();
  await expectStat(page, 'Moves', '0');
  await page.evaluate(() => {
    const region = document.querySelector('[aria-live]');
    if (!region) throw new Error('Missing live region');
    const events: string[] = [];
    new MutationObserver(() => {
      events.push(region.textContent ?? '');
      region.setAttribute('data-test-announcements', JSON.stringify(events));
    }).observe(region, { childList: true, subtree: true, characterData: true });
  });
  let position = 1;
  async function go(index: number) {
    while (position % 4 < index % 4) { await page.keyboard.press('ArrowRight'); position++; }
    while (position % 4 > index % 4) { await page.keyboard.press('ArrowLeft'); position--; }
    while (Math.floor(position / 4) < Math.floor(index / 4)) { await page.keyboard.press('ArrowDown'); position += 4; }
    while (Math.floor(position / 4) > Math.floor(index / 4)) { await page.keyboard.press('ArrowUp'); position -= 4; }
  }
  const deck = deckFor('np1-4-1');
  let revealedTree = '';
  for (let face = 0; face < 8; face++) {
    await go(deck.indexOf(face));
    await page.keyboard.press('Enter');
    if (face === 0) {
      revealedTree = await page.locator('main').ariaSnapshot();
      await expect(cards.nth(position)).toHaveAccessibleName('Row 1, column 3, cyan solid circle, marker top, revealed');
    }
    await go(deck.lastIndexOf(face));
    await page.keyboard.press('Space');
    await expect(cards.nth(position)).toHaveAttribute('aria-disabled', 'true');
    await expect(cards.nth(position)).toBeFocused();
  }
  await expect(page.locator('[aria-live]')).toHaveText(/Pair found\. All pairs found in 8 moves and \d+:\d\d\./);
  const announcements: unknown = JSON.parse(await page.locator('[aria-live]').getAttribute('data-test-announcements') ?? 'null');
  expect(Array.isArray(announcements) ? announcements.length : null).toBe(8);
  const completedTree = await page.locator('main').ariaSnapshot();
  expect(completedTree).toContain('All pairs found.');
  await page.keyboard.press('Tab');
  await expect(page.getByText('Reproduce a game', { exact: true })).toBeFocused();
  await page.getByRole('button', { name: 'New Game', exact: true }).focus();
  await page.keyboard.press('Enter');
  await expectStat(page, 'Moves', '0');
  mkdirSync('artifacts', { recursive: true });
  writeFileSync('artifacts/accessibility-journey.md', `# Automated keyboard and accessibility evidence\n\nChromium ${browser.version()}; Playwright 1.64.1. No screen reader was used. Spoken output needs user acceptance.\n\n## Closed board\n\n\`\`\`yaml\n${closedTree}\n\`\`\`\n\n## First reveal\n\n\`\`\`yaml\n${revealedTree}\n\`\`\`\n\n## Completion\n\n\`\`\`yaml\n${completedTree}\n\`\`\`\n\n## Turn announcements\n\n\`\`\`json\n${JSON.stringify(announcements, null, 2)}\n\`\`\`\n`);
});

test('consecutive identical results announce once each; timer and focus do not repeat them', async ({ page }) => {
  await page.clock.install();
  await page.goto('/');
  await loadBoard(page);
  const region = page.locator('[aria-live]');
  const cards = page.locator('.card');
  await cards.nth(0).click();
  await cards.nth(1).click();
  const first = await region.locator('span').evaluate(element => { element.setAttribute('data-test-original', 'yes'); return element.textContent; });
  await page.clock.runFor(800);
  await page.keyboard.press('ArrowRight');
  await expect(region.locator('[data-test-original]')).toHaveCount(1);
  await cards.nth(0).click();
  await cards.nth(1).click();
  await expect(region).toHaveText(first ?? '');
  await expect(region.locator('[data-test-original]')).toHaveCount(0);
  await page.clock.runFor(2000);
  await expect(region).toHaveText(first ?? '');
});

