import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { loadBoard, solve } from './helpers.ts';

async function outlineInView(page: Page) {
  const bounds = await page.locator('.card:focus').evaluate(element => {
    const card = element.getBoundingClientRect();
    const scroll = element.closest('.board-scroll')?.getBoundingClientRect();
    if (!scroll) throw new Error('Missing board scroll area');
    return { inside: card.left - 5 >= scroll.left && card.right + 5 <= scroll.right
      && card.top - 5 >= scroll.top && card.bottom + 5 <= scroll.bottom };
  });
  expect(bounds.inside).toBe(true);
}

for (const viewport of [{ width: 360, height: 800 }, { width: 1280, height: 800 }, { width: 640, height: 400 }]) {
  test(`layout, scrolling and focus at ${viewport.width}x${viewport.height}`, async ({ browser }) => {
    const context = await browser.newContext({ viewport, deviceScaleFactor: viewport.width === 640 ? 2 : 1, hasTouch: true });
    const page = await context.newPage();
    await page.goto('/');
    await loadBoard(page);
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
    const four = await page.locator('.card').first().boundingBox();
    expect(four?.width).toBeGreaterThanOrEqual(44);
    expect(four?.width).toBeLessThanOrEqual(88);
    await page.locator('.card').first().tap();
    await expect(page.locator('.card').first()).toHaveAccessibleName(/revealed/);
    await loadBoard(page, 'np1-16-1');
    await expect(page.locator('.card')).toHaveCount(256);
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
    const dimensions = await page.locator('.card').first().boundingBox();
    expect(dimensions?.width).toBeGreaterThanOrEqual(44);
    expect(dimensions?.height).toBe(dimensions?.width);
    const scroller = page.locator('.board-scroll');
    const bounds = await scroller.boundingBox();
    expect(bounds?.height).toBeLessThanOrEqual(viewport.height * .7 + 1);
    await page.locator('.card').first().focus();
    await outlineInView(page);
    for (let i = 0; i < 15; i++) await page.keyboard.press('ArrowRight');
    for (let i = 0; i < 15; i++) await page.keyboard.press('ArrowDown');
    await expect(page.locator('.card').last()).toBeFocused();
    await outlineInView(page);
    // Check a mid-board focus outline, which can be clipped without scroll-margin.
    for (let i = 0; i < 7; i++) await page.keyboard.press('ArrowLeft');
    for (let i = 0; i < 7; i++) await page.keyboard.press('ArrowUp');
    await outlineInView(page);
    await scroller.evaluate(element => { element.scrollTo(element.scrollWidth, element.scrollHeight); });
    await page.locator('.card').last().tap();
    await expect(page.locator('.card').last()).toHaveAccessibleName(/revealed/);
    await scroller.evaluate(element => { element.scrollTo(0, 0); });
    await page.locator('.card').first().tap();
    await expect(page.getByLabel('Grid size')).toBeEnabled();
    await context.close();
  });
}

test('reduced motion, single completion pulse, silence and a desktop screenshot', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.goto('/');
  await loadBoard(page);
  await page.getByText('Reproduce a game', { exact: true }).click();
  await page.screenshot({ path: 'artifacts/neon-pairs.png', fullPage: true });
  expect(await page.locator('.card').first().evaluate(element => getComputedStyle(element).transitionDuration)).toBe('0.12s');
  await solve(page);
  expect(await page.locator('.win-banner').evaluate(element => ({ duration: getComputedStyle(element).animationDuration,
    iterations: getComputedStyle(element).animationIterationCount }))).toEqual({ duration: '0.6s', iterations: '1' });
  await page.emulateMedia({ reducedMotion: 'reduce' });
  expect(await page.locator('.win-banner').evaluate(element => getComputedStyle(element).animationName)).toBe('none');
  expect(await page.locator('.card').first().evaluate(element => getComputedStyle(element).transitionDuration)).toBe('0s');
  await expect(page.locator('audio, video')).toHaveCount(0);
});

