import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { test, expect } from '@playwright/test';
import { expectStat, loadBoard, solve } from './helpers.ts';

test('the single distribution plays directly from disk with network blocked', async ({ browser }) => {
  const context = await browser.newContext({ offline: true });
  const page = await context.newPage();
  const errors: string[] = [];
  const remote: string[] = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('request', request => { if (/^https?:/.test(request.url())) remote.push(request.url()); });
  await page.goto(pathToFileURL(resolve('dist/index.html')).href);
  await expect(page.getByRole('heading', { name: 'Neon Pairs.' })).toBeVisible();
  await loadBoard(page);
  await solve(page);
  await expectStat(page, 'Moves', '8');
  await page.getByRole('button', { name: 'Restart', exact: true }).click();
  await expectStat(page, 'Moves', '0');
  expect(remote).toEqual([]);
  expect(errors).toEqual([]);
  const html = readFileSync('dist/index.html', 'utf8');
  expect(html).not.toMatch(/<script[^>]+src=|<link[^>]+(?:stylesheet|modulepreload)|<audio|AudioContext|speechSynthesis/);
  await context.close();
});

test('the documented replay command prints only a snapshot and rejects invalid files', () => {
  const directory = mkdtempSync(`${tmpdir()}/neon-pairs-`);
  const path = `${directory}/a replay.json`;
  try {
    writeFileSync(path, JSON.stringify({ version: 1, boardCode: 'np1-4-1',
      actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800 }));
    const stdout = execFileSync('npm', ['run', '--silent', 'replay', '--', path], { encoding: 'utf8' });
    const result: unknown = JSON.parse(stdout);
    expect(result).toEqual({ version: 1, boardCode: 'np1-4-1', matched: [0, 11], selection: { kind: 'closed' },
      moves: 1, elapsedMs: 800, started: true });
    writeFileSync(path, '{}');
    const invalid = spawnSync('npm', ['run', '--silent', 'replay', '--', path], { encoding: 'utf8' });
    expect(invalid.status).not.toBe(0);
    expect(invalid.stdout).toBe('');
    expect(invalid.stderr).toContain('Invalid replay.');
  } finally { rmSync(directory, { recursive: true }); }
});

