test('all 128 structural identities at 44px in a grayscale face sheet', async ({ page }) => {
  const names = Array.from({ length: 128 }, (_, id) => faceParts(id).name);
  expect(new Set(names).size).toBe(128);
  expect(names[0]).toBe('cyan solid circle, marker top');
  expect(names[64]).toBe('cyan outline circle, marker top');
  const faces = names.map((name, id) => `<figure title="${name}"><div class="tile">${renderToStaticMarkup(createElement(Face, { id }))}</div><figcaption>${id}</figcaption></figure>`).join('');
  const html = `<!doctype html><html lang="en"><meta charset="utf-8"><title>128 Neon Pairs faces at 44px, grayscale</title>
    <style>*{box-sizing:border-box}body{margin:0;padding:16px;background:#090b14;color:#f4f6ff;font:14px system-ui}
    h1{font-size:20px;margin:0 0 16px}section{display:grid;grid-template-columns:repeat(16,44px);gap:12px;filter:grayscale(1)}
    figure{margin:0}.tile{width:44px;height:44px;border:2px solid #757c9a;border-radius:8px;background:#111625}
    svg{display:block;width:100%;height:100%}figcaption{text-align:center;margin-top:4px}</style>
    <h1>128 faces · 44px · grayscale</h1><section>${faces}</section></html>`;
  mkdirSync('artifacts', { recursive: true });
  writeFileSync('artifacts/face-sheet.html', html);
